package io.knowledgebrain.content;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class QuestionApiTest {
 QuestionStore store;SpaceAuthorizationClient auth;QuestionController api;UUID space,id,actor;
 @BeforeEach void init(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();id=ids.next();actor=ids.next();store=mock(QuestionStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorizeQuestion(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);api=new QuestionController(store,auth,new SimpleMeterRegistry(),"https://localhost:8443");}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/questions");r.setSecure(true);r.setContentType("application/json");r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("If-Match","\"qu1\"");r.addHeader("Idempotency-Key","a".repeat(32));if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void exactFourFieldJsonStrongTagsAndStableKeysAreRequired()throws Exception{
  for(String body:List.of("{}","{\"title\":\"a\",\"context\":\"Context\",\"answer\":\"\",\"status\":\"ANSWERED\"}","{\"title\":\"a\",\"context\":\"Context\",\"answer\":null,\"status\":\"OPEN\"}","{\"title\":\"a\",\"context\":\"Context\",\"answer\":\"\",\"answer\":\"x\",\"status\":\"OPEN\"}","{\"title\":\"a\",\"context\":\"Context\",\"answer\":\"\",\"status\":\"OPEN\"} {}"))assertThrows(ResponseStatusException.class,()->api.create(space.toString(),r("POST",body)));
  String body="{\"title\":\"a\",\"context\":\"Context\",\"answer\":\"\",\"status\":\"OPEN\"}";
  var missing=r("PUT",body);missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.update(space.toString(),id.toString(),missing)).getStatusCode().value());
  for(String tag:List.of("\"nt1\"","\"qu0\"","W/\"qu1\"","*","\"qu01\"")){var q=r("PUT",body);q.removeHeader("If-Match");q.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.update(space.toString(),id.toString(),q));}
  var key=r("POST",body);key.removeHeader("Idempotency-Key");assertThrows(ResponseStatusException.class,()->api.create(space.toString(),key));assertEquals(413,assertThrows(ResponseStatusException.class,()->api.create(space.toString(),r("POST"," ".repeat(262145)))).getStatusCode().value());verifyNoInteractions(store);
 }
 @Test void currentReadsHaveNoCacheAndReauthorizeWithQuestionCapabilityEveryTime(){var value=new QuestionStore.Question(id,space,"PRIVATE","ACTIVE",1,"a","Context", "answer","OPEN",Instant.now().toString(),Instant.now().toString());when(store.get(space,id)).thenReturn(value);for(int n=0;n<2;n++){var response=api.get(space.toString(),id.toString(),r("GET",null));assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals("\"qu1\"",response.getHeaders().getETag());}verify(auth,times(2)).authorizeQuestion(eq(space),any(),eq(false),anyString());verify(auth,never()).authorize(any(),any(),anyBoolean(),any());reset(store);when(auth.authorizeQuestion(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.history(space.toString(),id.toString(),r("GET",null)));verifyNoInteractions(store);}
 @Test void badOriginInsecureRequestsAmbiguousSessionsAndQueriesCannotReachStore(){var q=r("DELETE",null);q.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.retire(space.toString(),id.toString(),q)).getStatusCode().value());var insecure=r("GET",null);insecure.setSecure(false);assertThrows(ResponseStatusException.class,()->api.list(space.toString(),insecure));var duplicate=r("GET",null);duplicate.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertEquals(401,assertThrows(ResponseStatusException.class,()->api.list(space.toString(),duplicate)).getStatusCode().value());var query=r("GET",null);query.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),query));assertThrows(ResponseStatusException.class,()->api.list(space.toString(),r("GET","{}")));verifyNoInteractions(store);}
}
